COPY public.verses (id, chapter_id, order_in_chapter, m1, m2) FROM stdin;
ac9f9f0d-f098-47cc-884d-07a032ade2c5	a148e7aa-3689-4c16-a34f-a7119de250dd	1	جهان چون به زاری برآید همی	بد و نیک روزی سرآید همی
80c0c325-e6de-417c-a689-d10027a96bcf	a148e7aa-3689-4c16-a34f-a7119de250dd	2	چو بستی کمر بر در راه آز	شود کار گیتیت یکسر دراز
f9e41f16-9d59-4c26-b140-d483f1c894ba	a148e7aa-3689-4c16-a34f-a7119de250dd	3	به یک روی جستن بلندی سزاست	اگر در میان دم اژدهاست
2cf582ef-cac2-413c-91e2-7c23ddfca267	a148e7aa-3689-4c16-a34f-a7119de250dd	4	و دیگر که گیتی ندارد درنگ	سرای سپنجی چه پهن و چه تنگ
a75af101-75a6-44e8-8a42-941a58b6427b	a148e7aa-3689-4c16-a34f-a7119de250dd	5	پرستنده ی آز و جویای کین	به گیتی ز کس نشنود آفرین
18407ba5-aabb-47c6-89b2-458d4f450b05	a148e7aa-3689-4c16-a34f-a7119de250dd	6	چو سرو سهی گوژ گردد به باغ	بدو بر شود تیره روشن چراغ
9de590c0-1b5f-4eb0-b67d-7b1816d4aae3	a148e7aa-3689-4c16-a34f-a7119de250dd	7	کند برگ پژمرده و بیخ سست	سرش سوی پستی گراید نخست
305e9e24-9273-4061-a09e-39e510e28c95	a148e7aa-3689-4c16-a34f-a7119de250dd	8	بروید ز خاک و شود باز خاک	همه جای ترسست و تیمار و باک
6c83a7ae-513f-484f-9fe5-d3d8bd6070a5	a148e7aa-3689-4c16-a34f-a7119de250dd	9	سر مایهٔ مرد سنگ و خرد	ز گیتی بیآزاری اندر خورد
08fd5745-b5cc-40be-b5a1-85beb22db9f2	a148e7aa-3689-4c16-a34f-a7119de250dd	10	در دانش و آنگهی راستی	گرین دو نیابی روان کاستی
6b909af9-dea5-475f-b9d4-291c4a46d5a8	a148e7aa-3689-4c16-a34f-a7119de250dd	11	اگر خود بمانی به گیتی دراز	ز رنج تن آید به رفتن نیاز
7723fd10-03d6-4852-a96d-9dfa012aac27	a148e7aa-3689-4c16-a34f-a7119de250dd	12	یکی ژرف دریاست بن ناپدید	در گنج رازش ندارد کلید
ba3d5334-7a02-48cd-b9d8-7d14dd29732e	a148e7aa-3689-4c16-a34f-a7119de250dd	13	اگر چند یابی فزون بایدت	همان خورده یک روز بگزایدت
1bcf25cf-9dd9-4ab2-a483-5ea69f0fd379	a148e7aa-3689-4c16-a34f-a7119de250dd	14	سه چیزت بباید کز آن چاره نیست	وزو بر سرت نیز پیغاره نیست
2ab1338c-2d24-4ed4-addf-ec0619d235fd	a148e7aa-3689-4c16-a34f-a7119de250dd	15	خوری گر بپوشی و گر گستری	سزد گر به دیگر سخن ننگری
534d5d52-6830-4c69-8b11-7d28fe3dcb25	a148e7aa-3689-4c16-a34f-a7119de250dd	16	چو زین سه گذشتی همه رنج و آز	چه در آز پیچی چه اندر نیاز
cf7d22c4-76dd-43b8-b128-a6f2bb6d04be	a148e7aa-3689-4c16-a34f-a7119de250dd	17	چو دانی که بر تو نماند جهان	چه پیچی تو زان جای نوشین روان
f7035702-661b-493b-b1e6-c414bae2c85d	a148e7aa-3689-4c16-a34f-a7119de250dd	18	بخور آنچه داری و بیشی مجوی	که از آز کاهد همی آبروی
c8756aa1-52b1-46bf-a102-f18def37eb25	12ba05dd-70da-4458-9a83-fed1a61059b9	1	دل شاه ترکان چنان کم شنود	همیشه به رنج از پی آز بود
a7630628-dad3-4b9a-9258-b9033baa3dbc	12ba05dd-70da-4458-9a83-fed1a61059b9	2	از آن پس که برگشت زان رزمگاه	که رستم بر او کرد گیتی سیاه
